import DeleteMemberconfig from "./DeleteMemberconfig.vue";
import { list_membership } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
import SnackBar from "@/components/SnackBar.vue";
import AddMemberconfig from "./AddMemberconfig.vue";
export default {
  components: {
    SnackBar,
    AddMemberconfig,
    DeleteMemberconfig
  },
  data() {
    return {
      height: 0,
      addconfigMember: false,
      membershipDelete: false,
      fixed: true,
      tableLoading: false,
      SnackBarComponent: {},
      componentCheck: 0,
      tableData: [],
      headers: [{
        text: "Name",
        value: "membership_name",
        sortable: false
      }, {
        text: "Description",
        value: "membership_description",
        sortable: false
      }, {
        text: "Validity",
        value: "membership_validity",
        sortable: false
      }, {
        text: "Created By",
        value: "membership_created_by",
        sortable: false
      }, {
        text: "Action",
        value: "actions",
        sortable: false
      }],
      rowInfo: {}
    };
  },
  async created() {
    this.get_members();
    this.height = window.innerHeight - 330;
  },
  methods: {
    add_action() {
      this.componentCheck = 1;
      this.addconfigMember = true;
    },
    delete_membership(item) {
      this.componentCheck = 2;
      this.membershipDelete = true;
      this.rowInfo = item;
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.membershipDelete = false;
      this.addconfigMember = false;
      this.get_members();
    },
    async get_members() {
      this.tableLoading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(list_membership, {
          input: {
            organization_id: data.organization.organization_id,
            limit: 100,
            nextToken: null
          }
        }));
        var response = JSON.parse(result.data.list_membership);
        if (response.Status == "SUCCESS") {
          this.tableData = response.data;
          this.tableLoading = false;
        } else {
          this.tableLoading = false;
        }
      } catch (error) {
        this.tableLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    }
  }
};
